import {sendParticipation} from './storage.js';
import {track,trackActivity} from './analytics.js';
import {Session,preQuestions,postQuestions,risks,shareText} from './model.js';
const app=document.querySelector('#app'),panel=document.querySelector('#panel'),help=document.querySelector('.help');
let session,observer,timer,storeDeadline,trigger;
const cloudStates=new Map();
async function upload(data){cloudStates.set(data.id,'sending');renderCloud();try{await sendParticipation(data);cloudStates.set(data.id,'saved')}catch{cloudStates.set(data.id,'failed')}renderCloud()}
function renderCloud(){const el=document.querySelector('#cloud-status');if(!el||!session)return;const state=cloudStates.get(session.data.id);el.textContent=state==='saved'?'Resultado salvo no Firebase.':state==='sending'?'Salvando resultado…':'O envio não foi concluído. Suas respostas continuam salvas neste navegador.';const retry=document.querySelector('[data-action=retry-cloud]');if(retry)retry.hidden=state!=='failed'}
function activityEvent(event,data){trackActivity(event,data);if(event.name==='respondeu_quiz_final')upload(structuredClone(data))}
let storageFailed=false,shippingAddress=null,shippingRequest=0;
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function save(data){try{localStorage.setItem('compras-seguras-session',JSON.stringify(data))}catch{storageFailed=true}}
function fresh(){shippingAddress=null;shippingRequest++;session=new Session({save,onEvent:activityEvent});session.visibility(!document.hidden);storeDeadline=null;session.persist();go('welcome')}
const button=(label,action,secondary=false)=>`<button data-action="${action}"${secondary?' class="secondary"':''}>${label}</button>`;
const art='<div class="hero-art"><img src="assets/fritadeira.svg" width="280" height="280" alt="Fritadeira elétrica Brisa 4 litros, produto fictício" style="max-width:100%;height:auto"></div>';
const adArt="<div class=\"hero-art ad-photo\"><img src=\"data:image/png;base64,\" width=\"411\" height=\"500\" alt=\"Foto ilustrativa de uma fritadeira elétrica preta\"></div>";
const guide=`<p class="lead">PARE • CONFIRA • COMPRE</p><ol class="checklist"><li><strong>PARE.</strong> Preço muito baixo, contagem regressiva e pressão para pagar merecem uma pausa.</li><li><strong>CONFIRA.</strong> Compare o endereço com o canal oficial. Verifique empresa, atendimento, reputação independente e quem recebe o pagamento. O cadeado não comprova a identidade da loja.</li><li><strong>COMPRE.</strong> Decida depois de verificar. Se houver suspeita, interrompa a compra.</li></ol><p class="muted">Use este guia sempre que precisar conferir uma oferta.</p>`;
const stages=['welcome','pre','guide','ad','store','checkout','mirror','post','result'];
const titles=['','Antes de começar','Guia de segurança','O anúncio','A loja','Pagamento fictício','Suas escolhas','O que você aprendeu','Resultado'];
function go(stage){observer?.disconnect();clearInterval(timer);session.changeStage(stage);track('activity_step',{activity_stage:stage});app.classList.toggle('store-view',stage==='store');app.classList.toggle('checkout-view',stage==='checkout');help.hidden=!['ad','store','checkout'].includes(stage);const i=stages.indexOf(stage);app.innerHTML=`<div class="step"><span>Etapa ${i+1} de 9</span><span>${titles[i]}</span></div>${screens[stage]()}`;app.querySelector('h1').tabIndex=-1;app.querySelector('h1').focus();window.scrollTo(0,0);if(stage==='result')renderCloud();if(stage==='store'){session.enterStore();storeDeadline??=performance.now()+299000;tick();timer=setInterval(tick,1000);observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))session.event('inspecionou_rodape')},{threshold:0.5});observer.observe(document.querySelector('#store-footer'))}}
function tick(){const el=document.querySelector('#countdown');if(!el)return;const seconds=Math.max(0,Math.ceil((storeDeadline-performance.now())/1000));el.textContent=seconds?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Oferta encerrada. Você pode continuar a atividade.'}
function quiz(kind){const qs=kind==='pre'?preQuestions:postQuestions;return `<h1>${kind==='pre'?'Antes de investigar':'Depois de investigar'}</h1><p>${kind==='pre'?'Responda antes de ver as dicas. O gabarito será apresentado apenas no resultado.':'Responda às três perguntas. As explicações aparecem após o envio.'}</p><form id="quiz" data-kind="${kind}">${qs.map((q,i)=>`<fieldset><legend>${i+1}. ${q.text}</legend>${q.options.map((option,j)=>`<label><input type="radio" name="q${i}" value="${j}"><span>${option}</span></label>`).join('')}</fieldset>`).join('')}<p id="quiz-error" class="error" role="alert"></p><button type="submit">${kind==='pre'?'Salvar respostas e ver o guia':'Ver resultado'}</button></form>`}
const screens={
 welcome:()=>`<p class="eyebrow">Aprenda na prática</p><h1>Uma oferta. Várias pistas. Sua decisão.</h1><p class="lead">Investigue uma compra fictícia e descubra o que conferir antes de pagar.</p><div class="learning-path" aria-label="O que você vai praticar"><div class="learning-step"><strong>1. Observe</strong><span>Veja o anúncio e o preço.</span></div><div class="learning-step"><strong>2. Investigue</strong><span>Confira a loja e o pagamento.</span></div><div class="learning-step"><strong>3. Decida</strong><span>Escolha e aprenda com as pistas.</span></div></div><div class="card welcome-info"><h2>Você pode explorar sem pressa</h2><p>A atividade tem nove etapas, com perguntas e uma simulação de compra. O produto, a loja e o pagamento são fictícios. Não são solicitados dados pessoais ou bancários.</p></div><div class="welcome-actions">${button('Começar a investigação','start')}<a class="button results-link" href="resultados.html" target="_blank" rel="noopener">Ver resultados gerais</a></div>`,
 pre:()=>quiz('pre'),
 guide:()=>`<h1>Três passos para investigar uma oferta</h1><div class="card">${guide}</div>${button('Continuar para o anúncio','ad')}`,
 ad:()=>`<p class="eyebrow">Casa Brisa • Oferta especial</p><h1>O que chama sua atenção nesta oferta?</h1><div class="grid">${adArt}<div><span class="tag scam-tag">LIQUIDAÇÃO RELÂMPAGO • 75% OFF</span><h2>Fritadeira Brisa • 4 litros</h2><p class="old">De R$ 799,00</p><p class="price">R$ 199,00</p><div class="offer-pressure"><strong>ÚLTIMAS 2 UNIDADES!</strong><p>“Você foi selecionado para esta oferta exclusiva. Compre agora para não perder o desconto!”</p><span>Oferta válida somente hoje • Estoque quase esgotado</span></div></div></div><p>Imagine que você quer avaliar essa compra. Você pode investigar ou interromper quando quiser.</p><div class="actions">${button('Visitar a loja fictícia','store')}${button('Desistir por suspeita','quit',true)}</div>`,
 store:()=>`<section class="retail"><div class="simulated-browser" aria-label="Barra de endereço da loja na atividade"><div class="simulated-tab">Casa Brisa — Fritadeira elétrica</div><div class="simulated-address"><button data-inspect="inspecionou_url" aria-label="Conferir endereço da loja">https://ofertas-casa-br1sa.invalid/fritadeira-brisa-4l</button></div></div><div class="retail-header"><strong class="retail-brand">CASA <span>BRISA</span></strong><span class="retail-search">Encontre seu próximo eletrodoméstico</span><span class="retail-delivery">Entrega em todo o Brasil</span></div><nav class="retail-nav" aria-label="Categorias da loja"><span>Departamentos</span><span>Eletrodomésticos</span><span>Eletroportáteis</span><span class="retail-coupon">Ofertas do dia</span></nav><p class="retail-breadcrumb">Casa Brisa / Eletroportáteis / Fritadeiras</p><h1>Fritadeira elétrica sem óleo Brisa 4 litros • 1.500 W • Preta</h1><p class="retail-code">Cód. do produto: BR-400</p><button class="url" data-inspect="inspecionou_url">Conferir endereço: ofertas-casa-br1sa.invalid</button><div class="retail-product"><div class="retail-gallery">${adArt}</div><div class="retail-details"><p>Vendido e entregue por <button class="retail-link" data-inspect="inspecionou_empresa">Casa Brisa Comércio</button></p><button class="retail-link" data-inspect="inspecionou_avaliacoes">5,0 / 5 • 8 avaliações</button><div class="retail-spec"><strong>Capacidade: 4 litros</strong><span>Cesto removível • Potência de 1.500 W</span></div><div class="retail-buy-row"><div class="retail-price"><p><span class="old">R$ 799,00</span> <span class="retail-discount">Baixou 75%</span></p><p class="price">R$ 199,00</p><p>ou em até <strong>6x de R$ 33,17</strong> sem juros</p></div>${button('Comprar','buy')}</div><button class="retail-link payment-options" data-inspect="inspecionou_pagamento">Ver mais opções de pagamento</button><button class="retail-link" data-inspect="inspecionou_preco">Comparar o preço da oferta</button><div class="retail-credit"><p>Talvez você tenha um <strong>crédito pré-aprovado.</strong> Que tal conferir?</p>${button('Ver agora','credit',true)}</div><div class="retail-shipping"><strong>Calcular o frete e prazo de entrega</strong><div class="retail-shipping-controls"><input id="shipping-cep" class="retail-postcode" type="text" inputmode="numeric" autocomplete="off" maxlength="9" placeholder="00000-000" aria-label="CEP para simulação" aria-describedby="shipping-result"><button data-action="shipping">Consultar</button></div><div id="shipping-result" role="status" hidden></div></div><div class="retail-urgency"><strong>Últimas 2 unidades</strong><span>A oferta termina em <span id="countdown"></span></span>${button('Ver condições da oferta','urgency',true)}</div></div></div><div class="actions">${button('Desistir por suspeita','quit',true)}</div><section class="customer-reviews" aria-label="Avaliações de clientes"><div class="rating-summary"><h2>Avaliações de clientes</h2><div class="rating-total"><strong>5,0</strong><div><span class="rating-stars" aria-label="5 de 5 estrelas">★★★★★</span><p>Total de 8 avaliações</p></div></div><div class="rating-bars">${[5,4,3,2,1].map(n=>`<div><span>${n} ${n===1?'estrela':'estrelas'}</span><meter min="0" max="100" value="${n===5?100:0}" aria-label="${n} estrelas: ${n===5?100:0}%"></meter><span>${n===5?100:0}%</span></div>`).join('')}</div><h3>Recomendação do produto</h3><div class="recommendation-grid"><div><strong>100%</strong><p>dos clientes <b>recomendam</b> esse produto.</p></div><div><strong>0%</strong><p>dos clientes <b>não recomendam</b> esse produto.</p></div></div><button class="secondary" data-inspect="inspecionou_avaliacoes">Investigar avaliações</button></div><div class="review-list"><div class="review-list-head"><h2>Principais avaliações</h2><label for="review-sort">Ordenar por <select id="review-sort"><option value="useful">Mais úteis</option><option value="asc">Nome: A a Z</option><option value="desc">Nome: Z a A</option></select></label></div><div id="review-items">${[['Mariana Souza','Gostei bastante. O cesto é fácil de limpar e a batata ficou crocante.'],['Paulo Henrique','Chegou antes do prazo. Já usei duas vezes e funcionou bem.'],['Luciana Ferreira','Achei que fosse um pouco maior, mas atende bem para duas pessoas.'],['Carlos Eduardo','Boa compra pelo preço. O controle de tempo é simples de usar.'],['Renata Oliveira','Fiz frango e pão de queijo. Gostei do resultado e da limpeza.'],['André Santos','Embalagem chegou em boas condições. Produto conforme o anúncio.'],['Camila Ribeiro','Ocupa pouco espaço na bancada. Estou usando quase todos os dias.'],['Juliana Costa','Esquenta rápido. Só precisei ajustar o tempo das receitas.']].map(([name,text],i)=>`<article class="customer-review" data-review-name="${name}" data-review-order="${i}"><h3>${name}</h3><div class="review-meta"><span class="rating-stars" aria-label="5 de 5 estrelas">★★★★★</span><span>Data não informada</span></div><p>${text}</p><div class="review-vote"><strong>Essa avaliação foi útil?</strong><button class="secondary" data-vote="yes" aria-pressed="false">Sim</button><button class="secondary" data-vote="no" aria-pressed="false">Não</button><span class="vote-result" role="status"></span></div></article>`).join('')}</div></div></section><footer id="store-footer" class="card"><h2>Informações da loja</h2><p>Casa Brisa Comércio • CNPJ: 00.000.000/0000-00</p><p>Rua da Simulação, 000 • Atendimento não informado</p><p>Trocas: “fale com a loja”.</p><button class="secondary" data-inspect="inspecionou_empresa">Conferir dados e políticas</button></footer></section>`,
 checkout:()=>`<section class="checkout-retail"><div class="checkout-brand retail-brand">CASA <span>BRISA</span></div><div class="checkout-title"><h1>Finalize sua compra</h1>${button('Voltar à loja','store',true)}</div><div class="checkout-columns"><div class="checkout-left"><h2>Pagamento</h2><div class="checkout-payment"><div><strong>Pix</strong><p>50% de desconto adicional no pagamento por Pix.</p></div><strong>R$ 99,50</strong></div><div class="checkout-info"><h3>Confira antes de pagar</h3><p>Verifique o nome do destinatário e sua relação com a loja antes de confirmar.</p><button class="retail-link" data-inspect="inspecionou_pagamento">Ver opções de pagamento</button></div><p class="checkout-card-unavailable">Cartão indisponível: “Sistema em manutenção, use Pix.”</p><h2>Endereço de envio</h2><div class="checkout-address"><strong>Casa</strong><p>${shippingAddress?escapeHtml(shippingAddress):'Consulte o CEP na loja para ver o endereço.'}</p><p>Entrega em até 2 dias úteis</p></div><h2>Destinatário do pagamento</h2><div class="checkout-recipient"><strong>Pessoa Exemplo da Simulação</strong><p>Pessoa física</p><button class="retail-link" data-inspect="inspecionou_destinatario">Conferir destinatário</button></div></div><aside class="checkout-order"><h2>Resumo do pedido</h2><div class="checkout-product">${adArt}<div><p>1 × Fritadeira elétrica Brisa 4 litros • 1.500 W • Preta</p><p>Vendido e entregue por <strong>Casa Brisa Comércio</strong></p><p>Entrega em até 2 dias úteis • Grátis</p></div></div><dl class="checkout-totals"><div><dt>Produto</dt><dd>R$ 199,00</dd></div><div><dt>Desconto no Pix (50%)</dt><dd>− R$ 99,50</dd></div><div><dt>Entrega</dt><dd>Grátis</dd></div><div class="checkout-total"><dt>Total</dt><dd>R$ 99,50</dd></div></dl>${button('Finalizar compra','confirm')}<p class="checkout-note">Nenhuma transferência será realizada.</p>${button('Desistir por suspeita','quit',true)}</aside></div></section>`,
 mirror:()=>`<h1>Vamos conferir as pistas?</h1><p class="lead">${session.data.outcome==='purchase'?'Você confirmou o pagamento na simulação. Agora veja quais pistas mereciam atenção.':'Você interrompeu a compra por suspeita. Agora confira as pistas que ajudam a avaliar essa oferta.'}</p><div class="card"><h2>O que foi registrado</h2><p>Tempo de análise com a aba visível: ${(session.data.analysisMs/1000).toFixed(1).replace('.',',')} segundos.${session.has('entrou_na_loja')?'':' Você encerrou antes de entrar na loja.'}</p><p>${session.has('compra_precipitada')?'Seu primeiro clique em comprar ocorreu antes de 15 segundos de análise. Essa é uma observação de tempo; não prova impulso ou compreensão.':'O tempo e os cliques não comprovam leitura, compreensão ou reconhecimento do golpe.'}</p><p>${session.has('inspecionou_rodape')?'O rodapé ficou visível. Isso não comprova que foi lido.':'Não houve registro do rodapé visível.'}</p><p>${session.has('consultou_infografico')?'Você abriu o guia durante a simulação.':'Não houve consulta ao guia durante a simulação. Você pode usá-lo nas próximas compras.'}</p></div><h2>As pistas da oferta</h2>${risks.map(r=>`<section class="card"><h3>${r.title}</h3><p><strong>${session.has(r.key)?'Detalhes abertos durante a atividade.':'Sem registro de abertura dos detalhes. Você pode conferir este sinal agora.'}</strong></p><p>${r.explanation}</p></section>`).join('')}${button('Conferir o que aprendi','post')}`,
 post:()=>quiz('post'),
 result:()=>`<h1>O que você aprendeu?</h1><p id="cloud-status" role="status"></p><button data-action="retry-cloud" hidden>Tentar salvar novamente</button><div class="card"><h2>Seu aprendizado nesta atividade</h2><p class="lead">Antes da atividade: ${session.data.pre.score}/3 • Depois da atividade: ${session.data.post.score}/3</p><p>${session.data.post.score>session.data.pre.score?'Você acertou mais perguntas após a atividade.':session.data.post.score===session.data.pre.score?'Sua pontuação se manteve.':'Sua pontuação foi menor no questionário final. Revise as explicações e pratique novamente.'} Esta comparação descreve o desempenho imediato nesta sessão; não mede retenção posterior.</p><table><thead><tr><th>Objetivo</th><th>Antes</th><th>Depois</th></tr></thead><tbody>${preQuestions.map((q,i)=>`<tr><td>${q.objective}</td><td>${session.data.pre.answers[i]===q.correct?'Acertou':'Errou'}</td><td>${session.data.post.answers[i]===postQuestions[i].correct?'Acertou':'Errou'}</td></tr>`).join('')}</tbody></table></div><h2>Respostas explicadas</h2>${['pre','post'].map(kind=>`<h3>${kind==='pre'?'Antes de investigar':'Depois de investigar'}</h3>${(kind==='pre'?preQuestions:postQuestions).map((q,i)=>`<div class="card"><p><strong>${i+1}. ${q.text}</strong></p><p>Sua resposta: ${q.options[session.data[kind].answers[i]]}</p><p>Resposta correta: ${q.options[q.correct]}</p><p>${q.explanation}</p></div>`).join('')}`).join('')}<section class="card summary"><h2>PARE • CONFIRA • COMPRE</h2><p>Pare diante da pressa. Confira endereço oficial, dados da empresa, reputação independente e destinatário do pagamento. Compre depois de verificar; na dúvida, interrompa.</p><div class="actions">${button('Compartilhar orientações','share')}${button('Copiar orientações','copy',true)}</div><p id="share-status" role="status"></p></section><div class="actions">${button('Investigar novamente','restart')}</div><div class="results-access"><a class="button results-link" href="resultados.html" target="_blank" rel="noopener">Ver resultados gerais</a></div>`
};
function openPanel(title,body){trigger=document.activeElement;document.querySelector('#panel-title').textContent=title;document.querySelector('#panel-body').innerHTML=body;panel.showModal();document.querySelector('#close-panel').focus()}
function closePanel(){panel.close()}
panel.addEventListener('close',()=>trigger?.isConnected&&trigger.focus());
document.querySelector('#close-panel').addEventListener('click',closePanel);
document.querySelector('#tips').addEventListener('click',()=>{session.event('consultou_infografico');openPanel('Dicas de segurança',guide)});
document.addEventListener('visibilitychange',()=>session.visibility(!document.hidden));
document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();app.querySelector('h1').focus()});
app.addEventListener('click',async event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.dataset.inspect){const risk=risks.find(r=>r.key===target.dataset.inspect);session.event(risk.key);openPanel(risk.title,`<p>${risk.detail}</p>`);return}
 if(target.dataset.vote){const group=target.closest('.review-vote');group.querySelectorAll('[data-vote]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));group.querySelector('.vote-result').textContent='Opinião registrada nesta tela.';return}
 const action=target.dataset.action;
 if(action==='shipping'){
 const input=document.querySelector('#shipping-cep'),result=document.querySelector('#shipping-result'),cep=input.value.replace(/\D/g,'');result.hidden=false;shippingAddress=null;
 if(cep.length!==8){input.setAttribute('aria-invalid','true');result.textContent='Digite um CEP com 8 números, como 01001-000.';input.focus();return}
 input.removeAttribute('aria-invalid');const request=++shippingRequest;target.disabled=true;result.textContent='Consultando endereço…';
 try{const response=await fetch('https://viacep.com.br/ws/'+cep+'/json/',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('service');const address=await response.json();if(request!==shippingRequest||!result.isConnected||input.value.replace(/\D/g,'')!==cep)return;if(address.erro){result.textContent='CEP não encontrado. Confira os números e tente novamente.';return}shippingAddress=[address.logradouro,address.bairro,[address.localidade,address.uf].filter(Boolean).join(' — ')].filter(Boolean).join(', ');result.innerHTML='<div class="shipping-address">'+escapeHtml(shippingAddress)+'</div><div class="shipping-delivery"><strong>Receba em casa</strong><div class="shipping-delivery-row"><span>Normal</span><strong>em até 2 dias úteis</strong><strong class="shipping-cost">Grátis</strong></div><button class="retail-link shipping-rules" data-action="shipping-rules">Ver regras de frete</button></div>';}catch{if(request===shippingRequest&&result.isConnected)result.textContent='Não foi possível consultar o CEP agora. Tente novamente.'}finally{target.disabled=false}return;
 }
 if(action==='shipping-rules')openPanel('Regras de frete','<p>O endereço é consultado no ViaCEP. O prazo e o valor do frete são simulados e não representam uma entrega real.</p><p>A loja anuncia entrega gratuita em até 2 dias úteis para qualquer região, sem informar a transportadora. Verifique se essa promessa é plausível antes de pagar.</p>');
 if(action==='credit')openPanel('Crédito na simulação','<p>Esta oferta de crédito é fictícia. Não há análise, contratação nem coleta de dados pessoais.</p><p>Uma promessa de crédito pré-aprovado não comprova a confiabilidade de uma loja. Confira a empresa e as condições antes de fornecer seus dados.</p>');
 if(action==='retry-cloud')upload(structuredClone(session.data));
 if(action==='start')go('pre');
 if(action==='ad'){session.event('apresentou_guia_inicial');go('ad')}
 if(action==='store')go('store');
 if(action==='urgency'){session.event('inspecionou_urgencia');const risk=risks.find(r=>r.key==='inspecionou_urgencia');openPanel(risk.title,`<p>${risk.detail}</p>`)}
 if(action==='buy'){session.buy();go('checkout')}
 if(action==='quit'){session.decide('quit');go('mirror')}
 if(action==='confirm'){session.decide('purchase');go('mirror')}
 if(action==='post')go('post');
 if(action==='restart')fresh();
 if(action==='erase'){try{localStorage.removeItem('compras-seguras-session');document.querySelector('#status').textContent='Registro local apagado.'}catch{document.querySelector('#status').textContent='Não foi possível acessar o armazenamento.'}}
 if(action==='copy'){try{await navigator.clipboard.writeText(shareText);document.querySelector('#share-status').textContent='Dicas copiadas. Você pode colar em uma mensagem.'}catch{manualCopy()}}
 if(action==='share'){if(!navigator.share){manualCopy();return}try{await navigator.share({title:'Compras Seguras',text:shareText});document.querySelector('#share-status').textContent='Dicas compartilhadas.'}catch(error){if(error.name==='AbortError')document.querySelector('#share-status').textContent='Compartilhamento cancelado. Você pode continuar.';else manualCopy()}}
});
function manualCopy(){openPanel('Copiar orientações manualmente','<p>Selecione o texto abaixo e use a opção Copiar do seu dispositivo.</p><label for="copy-text">Texto das dicas</label><textarea id="copy-text" readonly></textarea>');const text=document.querySelector('#copy-text');text.value=shareText;text.focus();text.select()}
app.addEventListener('change',event=>{if(event.target.id!=='review-sort')return;const container=app.querySelector('#review-items'),items=[...container.children],mode=event.target.value;items.sort((a,b)=>mode==='useful'?Number(a.dataset.reviewOrder)-Number(b.dataset.reviewOrder):(mode==='asc'?1:-1)*a.dataset.reviewName.localeCompare(b.dataset.reviewName,'pt-BR'));items.forEach(item=>container.append(item))});
app.addEventListener('input',event=>{if(event.target.id!=='shipping-cep')return;shippingAddress=null;shippingRequest++;const result=app.querySelector('#shipping-result');if(result)result.hidden=true;const input=event.target,digits=input.value.replace(/\D/g,'').slice(0,8);input.value=digits.length>5?digits.slice(0,5)+'-'+digits.slice(5):digits;input.removeAttribute('aria-invalid')});
app.addEventListener('keydown',event=>{if(event.target.id==='shipping-cep'&&event.key==='Enter'){event.preventDefault();app.querySelector('[data-action=shipping]').click()}});
app.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id!=='quiz')return;const answers=[0,1,2].map(i=>{const value=new FormData(form).get(`q${i}`);return value===null?null:Number(value)});if(answers.includes(null)){document.querySelector('#quiz-error').textContent='Responda às três perguntas para continuar.';form.querySelector(`input[name=q${answers.indexOf(null)}]`).focus();return}session.quiz(form.dataset.kind,answers);go(form.dataset.kind==='pre'?'guide':'result')});
fresh();
